import{sourceBytes,sourceText}from'./source-archive.js';
export const ENGINE_NAMES={pokefirered:'FireRed decomp',pokeemerald:'Emerald decomp',cfru:'Complete FireRed Upgrade',shiny:'Shiny’s CFRU Expansion'};
const locks=new Set(['SAVE_BLOCK_EXPANSION','EXPANDED_NEW_ITEMS','EXPANDED_TMSHMS','EXPANDED_MOVE_TUTORS','EXPANDED_TEXT_BUFFERS','EXPAND_MOVESETS','REPLACE_SOME_VANILLA_SPECIALS','BW_START_MENU_COMPATIBILITY','GEN4_PLUS_SELECTION_SCREEN','EXPAND_TRAINERS','NEW_BAG_UI_EXPANSION','SIDEWAY_STAIRS_IMPLEMENTED','FOSSIL_IMAGE_HACK','SET_HEALING_PLACE_HACK']);
const labels={ENABLE_FOLLOWER_POKEMON:'Following Pokémon',MEGA_EVOLUTION_FEATURE:'Mega Evolution',DYNAMAX_FEATURE:'Dynamax & Raid Battles',TERASTAL_FEATURE:'Terastallization',DEBUG_OVERWORLD_MENU:'Overworld debug menu',ONLY_CHECK_ITEM_FOR_HM_USAGE:'Use HMs from the bag',REUSABLE_TMS:'Reusable TMs',DELETABLE_HMS:'Forget HM moves normally',TIME_ENABLED:'Time of day',DNS_IN_BATTLE:'Day/night in battles',BW_SUMMARY_SCREEN:'Black/White summary screen',NATURE_COLORS_ON_SUMMARY_SCREEN:'Nature colours & IV ranks',MID_BATTLE_EVO:'Mid-battle evolution',SIDEQUEST_MENU:'Sidequest menu',HQ_MUSIC:'High-quality music mixer',OW_SHADOWS:'Overworld shadows',NEW_BATTLE_TEXTBOX:'Dark battle UI',OLD_MOVE_SPLIT:'Type-based physical/special split',NEW_MINI_NAME_BOX:'Mini name box',NO_POISON_IN_OW:'Disable overworld poison damage',INSTANT_TEXT:'Instant text',BW_REPEL_SYSTEM:'Offer another Repel',CAN_RUN_IN_BUILDINGS:'Run indoors',FOOTSTEP_NOISES:'Footstep sounds',ITEM_PICTURE_ACQUIRE:'Item pictures on pickup',ITEM_DESCRIPTION_ACQUIRE:'Item descriptions on pickup',SHOW_TERA_TYPE_ICON_ON_SUMMARY_SCREEN:'Tera type icon on summary',OPEN_WORLD_TRAINERS:'Scale trainer teams for open worlds'};
const numbers={MAX_POKEVIAL_USES:[1,99],OW_SHADOW_OPACITY:[0,16],STANDARD_IV:[0,31],SWARM_CHANCE:[0,100],WILD_DOUBLE_RANDOM_CHANCE:[0,100],EGG_HATCH_LEVEL:[1,100],AI_TRY_TO_KILL_RATE:[0,100],BIKE_ENCOUNTER_PERCENT:[0,100],SAFARI_ZONE_MAX_STEPS:[1,65535],SAFARI_ZONE_BALL_START:[1,255],MAX_SAFARI_BALLS:[1,255]};
const deps={DNS_IN_BATTLE:['TIME_ENABLED'],DEBUG_MEGA:['MEGA_EVOLUTION_FEATURE'],DEBUG_DYNAMAX:['DYNAMAX_FEATURE'],DEBUG_TERASTAL:['TERASTAL_FEATURE'],SHOW_TERA_TYPE_ICON_ON_SUMMARY_SCREEN:['TERASTAL_FEATURE'],ITEM_DESCRIPTION_ACQUIRE:['ITEM_PICTURE_ACQUIRE'],FOG_IN_BATTLE_1:['FOG_IN_BATTLE'],FOG_IN_BATTLE_2:['FOG_IN_BATTLE'],FOG_IN_BATTLE_3:['FOG_IN_BATTLE']};
const conflicts=[['BW_SUMMARY_SCREEN','NATURE_COLORS_ON_SUMMARY_SCREEN'],['OPEN_WORLD_TRAINERS','EXPAND_TRAINERS'],['CRIT_CHANCE_GEN_6','CRIT_CHANCE_GEN_2_TO_5'],['OLD_CONFUSION_HEAL_BERRIES','GEN_7_CONFUSION_HEAL_BERRIES']];
const title=n=>labels[n]||n.toLowerCase().split('_').map(w=>w[0]?.toUpperCase()+w.slice(1)).join(' ');
const category=n=>/DEBUG|SKIP_INTRO|REMOVE_OAK/.test(n)?'Development':/HM|TM|TUTOR/.test(n)?'Field moves & teaching':/FOLLOW|OW_|TIME_|DNS_|FOOTSTEP|RUN_|POISON|REPEL|NPC|STAIR|DOOR|BIKE/.test(n)?'World & travel':/SCREEN|MENU|TEXT|UI|BOX|ICON|DISPLAY|SUMMARY|ACQUIRE|NAME|HEALTH/.test(n)?'Interface':/MUSIC|CRY/.test(n)?'Audio':/BATTLE|MEGA|DYNAMAX|TERA|CRIT|DAMAGE|CONFUSION|EXP_|CAPTURE|WEATHER|TERRAIN|FROSTBITE|POWER|BOOST|NERF/.test(n)?'Battle & progression':'Other features';
export function detectSourceEngine(files){const has=p=>files.has(p),text=p=>has(p)?sourceText(files.get(p)):'';if(has('scripts/make.py')&&has('src/config.h')&&has('hooks')&&has('BPRE.ld'))return /Shiny|Tha Code Mining|CFRU.expansion/i.test(text('README.md'))||/ENABLE_FOLLOWER_POKEMON|TERASTAL_FEATURE/.test(text('src/config.h'))?'shiny':'cfru';if(has('Makefile')&&has('src/main.c')&&has('data/layouts/layouts.json')&&has('include/global.h')){if(/firered/i.test(text('Makefile'))||has('firered.ld'))return'pokefirered';if(/emerald/i.test(text('Makefile'))||has('emerald.ld'))return'pokeemerald';}throw Error('Not a recognised FireRed/Emerald decomp or CFRU source project. Import its root configuration and build files.');}
export function scanFeatures(files,engine=detectSourceEngine(files)){const paths=[...files.keys()].filter(p=>['cfru','shiny'].includes(engine)?p==='src/config.h':/^include\/config(?:\/[^/]+)?\.h$/.test(p)),rows=[];for(const path of paths){const text=sourceText(files.get(path));let block=false,depth=0,guard=false;text.split('\n').forEach((raw,line)=>{const wasBlock=block;let clean='';for(let i=0;i<raw.length;){if(block){const e=raw.indexOf('*/',i);if(e<0)break;block=false;i=e+2;}else{const e=raw.indexOf('/*',i);if(e<0){clean+=raw.slice(i);break;}clean+=raw.slice(i,e);block=true;i=e+2;}}if(wasBlock||block)return;if(/^\s*#\s*(if|ifdef|ifndef)\b/.test(clean)){if(!depth&&/^\s*#\s*ifndef\s+\w*(?:_H|_H_)\s*$/.test(clean))guard=true;depth++;return;}if(/^\s*#\s*endif\b/.test(clean)){depth=Math.max(0,depth-1);if(!depth)guard=false;return;}const m=clean.match(/^(\s*)(\/\/\s*)?#\s*define\s+([A-Za-z_]\w*)([^\r]*)(\r?)$/);if(!m||/^\(/.test(m[4])||/\\\s*$/.test(m[4]))return;const name=m[3],[value,comment='']=m[4].split(/\s*\/\/(.*)/s),literal=value.trim(),num=numbers[name];if(/(?:_H|_H_)$/.test(name)||['ENGLISH','GERMAN','JAPANESE','UNITS_IMPERIAL','UNITS_METRIC','NDEBUG'].includes(name)||literal&&!num||num&&!/^\d+$/.test(literal))return;const reason=locks.has(name)?'Requires additional table, hook or save-layout changes. Kept at the imported value.':depth>(guard?1:0)?'Inside a conditional block; edit in the source project.':num&&m[2]?'Numeric option is commented out; edit activation in source.':new RegExp('^\\s*#\\s*undef\\s+'+name+'\\b','m').test(text)?'Also undefined elsewhere in the header; edit in source.':null;rows.push({id:path+'::'+name,path,line,name,label:title(name),category:category(name),description:comment.trim(),type:num?'number':'boolean',value:num?Number(literal):!m[2],...(num?{min:num[0],max:num[1]}:{}),locked:!!reason,reason});});}const counts=new Map();for(const r of rows)counts.set(r.name,(counts.get(r.name)||0)+1);for(const r of rows)if(counts.get(r.name)>1){r.locked=true;r.reason='Multiple definitions found; edit in source.';}return rows;}
export function featureProblems(rows,changes={}){const issues=[],names=new Map(rows.map(r=>[r.name,Object.hasOwn(changes,r.id)?changes[r.id]:r.value])),touched=n=>rows.some(r=>r.name===n&&Object.hasOwn(changes,r.id));for(const[id,v]of Object.entries(changes)){const r=rows.find(r=>r.id===id);if(!r)issues.push('Saved feature missing: '+id);else if(r.locked)issues.push(r.label+': '+r.reason);else if(r.type==='boolean'?typeof v!=='boolean':!Number.isInteger(v)||v<r.min||v>r.max)issues.push('Invalid setting: '+r.label);}for(const[n,ds]of Object.entries(deps))if(names.get(n)&&ds.some(d=>!names.get(d))&&[n,...ds].some(touched))issues.push(title(n)+' requires '+ds.map(title).join(' and ')+'.');for(const[a,b]of conflicts)if(names.get(a)&&names.get(b)&&[a,b].some(touched))issues.push(title(a)+' conflicts with '+title(b)+'.');if(names.get('FOG_IN_BATTLE')&&!['FOG_IN_BATTLE_1','FOG_IN_BATTLE_2','FOG_IN_BATTLE_3'].some(n=>names.get(n))&&['FOG_IN_BATTLE','FOG_IN_BATTLE_1','FOG_IN_BATTLE_2','FOG_IN_BATTLE_3'].some(touched))issues.push('Battle fog needs at least one fog weather trigger.');return issues;}
export function applyFeatures(files,rows,changes={}){const issues=featureProblems(rows,changes);if(issues.length)throw Error(issues.join('\n'));const out=new Map(files);for(const path of new Set(rows.filter(r=>Object.hasOwn(changes,r.id)).map(r=>r.path))){const lines=sourceText(files.get(path)).split('\n');for(const r of rows.filter(r=>r.path===path&&Object.hasOwn(changes,r.id)))lines[r.line]=r.type==='boolean'?lines[r.line].replace(/^(\s*)(?:\/\/\s*)?(#\s*define\s+)/,(_,space,head)=>space+(changes[r.id]?'':'//')+head):lines[r.line].replace(new RegExp('(#\\s*define\\s+'+r.name+'\\s+)\\d+'),(_,head)=>head+changes[r.id]);out.set(path,sourceBytes(lines.join('\n')));}return out;}
export function runtimeSettings(files,engine){if(!['cfru','shiny'].includes(engine))return[];const text=sourceText(files.get('src/config.h'));return[['FLAG_NUZLOCKE','Nuzlocke'],['VAR_GAME_DIFFICULTY','Difficulty'],['FLAG_SANDBOX_MODE','Sandbox'],['FLAG_EXP_SHARE','Party Exp. Share'],['FLAG_HARD_LEVEL_CAP','Level cap'],['FLAG_PORTABLE_PC','Portable PC']].flatMap(([symbol,label])=>{const m=text.match(new RegExp('^\\s*#define\\s+'+symbol+'\\s+(0x[\\da-fA-F]+|\\d+)\\b','m'));return m?[{symbol,label,address:Number(m[1]),kind:symbol.startsWith('VAR_')?'variable':'flag'}]:[];});}
